// Every character a drawing shows exists in the font that draws it. A character the font lacks
// falls back to some other font on the viewer's computer, and its marks and size change.
// The code points of each embedded font are in src/shared/font/coverage.ts, generated by
// scripts/fonts/coverage.ts (npm run fonts) from the fonts themselves.
//
// A new language adds an entry to LANGUAGES: the faces that draw it and where its strings come from.
// Text that Claude draws in its own font (the thikr phrases on the spinner and status line) is not ours to check.
import { expect, test } from 'claude-code/testing'
import { covers, FONT_COVERAGE } from '../../../src/shared/font/coverage.ts'
import { ATHKAR } from '../../../src/features/athkar/data.ts'
import { AFTER_SALAH } from '../../../src/features/athkar/after-salah.ts'
import { END, END_NOTE } from '../../../src/features/athkar/logic.ts'
import { ATHKAR_TITLE } from '../../../src/shared/athkar/titles.ts'
import { ARABIC } from '../../../src/shared/pray/names.ts'
import { athanText, arabicDigits } from '../../../src/shared/pray/line.ts'
import { START_LABEL } from '../../../src/features/salah/card.ts'
import { QURAN_RECITERS, QURAN_SURAHS } from '../../../src/features/quran/catalog-data.ts'
import { athan, feeds, pane, settings } from '../../fixtures/drawings.ts'

// Characters that need no glyph of ours: spaces and direction marks.
const INVISIBLE = /[\s​-‏؜‪-‮⁦-⁩﻿]/u
// Characters drawn by the system on purpose, with why.
const SYSTEM: Record<number, string> = {
  0x1f932: 'the closing greeting is an emoji (palms up together), drawn by the system emoji font',
}

// Gaps found when this test was written: the character is shown, its font lacks it, and the viewer's
// system font draws it instead. Each is reported to the maintainer; none changes any text. The test
// fails on any other gap, and fails when a listed gap is closed (remove it then).
const KNOWN_GAPS: readonly { face: string; codePoint: number; why: string }[] = [
  ...['tajawal-band-400', 'tajawal-band-700'].flatMap(face => [
    { face, codePoint: 0x2713, why: '✓ in the done note «أَتْمَمْتَ وِرْدَكَ ✓» is a symbol the athkar subset never had' },
    { face, codePoint: 0x061f, why: '؟ in the question «أتممتَ الأذكار؟» is not in the athkar subset (the pane font has it)' },
  ]),
  ...[0x0639, 0x062f, 0x0629].map(codePoint => ({ face: 'aref-ruqaa-band-700', codePoint, why: 'the cover title of the after-salah set «أَذْكَارُ بَعْدَ الصَّلَاةِ» uses letters the morning and evening titles do not; Aref Ruqaa lacks them here and Tajawal draws them' })),
  ...['tajawal-pane-400', 'tajawal-pane-700'].flatMap(face => [
    { face, codePoint: 0x2713, why: '✓ on the athkar row button «أتممتُها ✓»' },
    { face, codePoint: 0x2191, why: '↑ in the list sheet footer «Use ↑ ↓ for scrolling»' },
    { face, codePoint: 0x2193, why: '↓ in the list sheet footer «Use ↑ ↓ for scrolling»' },
    { face, codePoint: 0x06cc, why: 'ی (Farsi yeh) in a reciter name of the Quran catalog' },
  ]),
]
const isKnown = (face: string, codePoint: number) => KNOWN_GAPS.some(g => g.face === face && g.codePoint === codePoint)

const unique = (texts: readonly string[]) => [...new Set(texts.join('').normalize('NFC'))].map(c => c.codePointAt(0)!)

// What a drawing writes as text, without its markup, style blocks and attributes.
const textOf = (svg: string) => svg.replace(/<style[\s\S]*?<\/style>/g, ' ').replace(/<[^>]*>/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&')

const gaps = (faces: readonly string[], texts: readonly string[]) =>
  faces.flatMap(face => unique(texts).filter(cp => !INVISIBLE.test(String.fromCodePoint(cp)) && !(cp in SYSTEM) && !covers(face, cp)).map(cp => ({ face, cp })))
const named = (g: { face: string; cp: number }) => `${g.face}: U+${g.cp.toString(16).toUpperCase().padStart(4, '0')} ${String.fromCodePoint(g.cp)}`

const panes = () => [
  pane(420, 'dark'), pane(240, 'light'), pane(420, 'dark', undefined, true),
  ...(['general', 'prayer', 'athkar', 'thikr'] as const).map(c => pane(420, 'dark', settings(c))),
  ...(['methods', 'adjust', 'city'] as const).map(f => pane(420, 'dark', settings('prayer', f))),
]

type Source = { name: string; faces: readonly string[]; texts: () => readonly string[] }

const LANGUAGES: Record<string, readonly Source[]> = {
  ar: [
    {
      name: 'the athkar band, the reading and the folded row',
      faces: ['tajawal-band-400', 'tajawal-band-700'],
      texts: () => [...ATHKAR.flatMap(t => [t.text, t.note ?? '']), ...AFTER_SALAH.flatMap(t => [t.text, t.note ?? '']), ...Object.values(ATHKAR_TITLE), ...Object.values(END_NOTE), END, 'أتممتَ الأذكار؟', 'دون عدّ كامل', 'نعم، أتممتُها', 'أكمل العدّ', arabicDigits('0123456789'), ' مِنْ ·'],
    },
    { name: 'the athkar cover title', faces: ['aref-ruqaa-band-700'], texts: () => Object.values(ATHKAR_TITLE) },
    {
      name: 'the athan card',
      faces: ['aref-ruqaa-athan-700'],
      texts: () => [...Object.keys(ARABIC).map(p => athanText(p as keyof typeof ARABIC)), arabicDigits('0123456789:'), START_LABEL, textOf(athan('', false)), textOf(athan('', true))],
    },
    {
      name: 'the Muslim pane',
      faces: ['tajawal-pane-400', 'tajawal-pane-700'],
      texts: () => [...panes().map(textOf), ...QURAN_SURAHS.map(s => s.name), ...QURAN_RECITERS.flatMap(r => [r.name, r.label]), ...ATHKAR.map(t => t.note ?? ''), ...Object.values(ATHKAR_TITLE), feeds.quran.reciter, feeds.quran.surah],
    },
  ],
}

for (const [language, sources] of Object.entries(LANGUAGES)) {
  for (const source of sources) {
    test(`${language}: every character of ${source.name} is in ${source.faces.join(' and ')}`, () => {
      expect(source.texts().join('').length).toBeGreaterThan(20)
      expect(gaps(source.faces, source.texts()).filter(g => !isKnown(g.face, g.cp)).map(named)).toEqual([])
    })
  }
}

test('every face the coverage names exists, and a face covers what its text uses', () => {
  const named = Object.values(LANGUAGES).flatMap(sources => sources.flatMap(s => s.faces))
  for (const face of named) expect(FONT_COVERAGE[face]?.length).toBeGreaterThan(0)
  expect(covers('tajawal-pane-400', 0x0651)).toBe(true)
  expect(covers('tajawal-pane-400', 0x4e2d)).toBe(false)
})

test('every known gap is still a gap, so the list stays true', () => {
  const all = Object.values(LANGUAGES).flat().flatMap(source => gaps(source.faces, source.texts()))
  const stale = KNOWN_GAPS.filter(k => !all.some(g => g.face === k.face && g.cp === k.codePoint)).map(k => named({ face: k.face, cp: k.codePoint }))
  expect(stale).toEqual([])
})
